{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C22"],
      "claim": "Testosterone undecanoate, a highly lipophilic long-chain fatty acid ester prodrug, has a mean absolute oral bioavailability of only 6.8% in humans, supporting low F for the similarly lipophilic ester/lactone query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Dimethandrolone undecanoate, another long-chain undecanoate ester, shows poor and inconsistent oral bioavailability, consistent with low systemic exposure for highly lipophilic ester prodrugs.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Perindopril, an ester prodrug, has an oral bioavailability of 19% ± 7% in healthy subjects, below the 20% threshold, supporting low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Pravastatin has an absolute oral bioavailability of 17% in humans, below 20%, supporting low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Laninamivir octanoate, a lipophilic ester prodrug, is only 15% orally bioavailable in humans, supporting low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "DVAS, a dodecyl ester dipeptide prodrug, showed an average oral bioavailability of 60% in healthy volunteers; however, its low transferability limits its weight, and the higher-transfer lipophilic ester evidence favors low F.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a highly lipophilic, poorly soluble ester/lactone with a long alkyl chain, closely resembling long-chain fatty acid ester prodrugs. High-transfer analogues such as testosterone undecanoate and dimethandrolone undecanoate show low absolute oral bioavailability (6.8% and poor/inconsistent), and other ester prodrugs (perindopril, pravastatin, laninamivir octanoate) fall below 20%. The few high-F analogues have low transferability and do not outweigh this consistent pattern. Therefore, F < 20% is predicted.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement for the query molecule is provided.",
    "Most analogues are not structurally identical, so transfer relies on shared lipophilic ester/lactone and long-chain features.",
    "High-F contradictory analogues have low transfer scores and limited structural overlap."
  ],
  "new_evidence_assessment": [
    {
      "applicability": "high",
      "card_ids": ["C22", "C28"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "long-chain lipophilic ester prodrugs"
    },
    {
      "applicability": "low",
      "card_ids": ["C12"],
      "decision_effect": "no_change",
      "direction": "contradictory",
      "family": "lipophilic dipeptide ester prodrugs"
    }
  ],
  "revision_action": "initial"
}

